#!/usr/bin/env node
// The content gate a site runs in CI (`npm run validate:content`). Generated by fizlet-engine
// `fe content collections`, with validate.mjs and the schemas beside it; never hand-edit.
// Fails when a collection file or this contract was edited by hand, or the content breaks the model.
import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { checkModel, checkStamp, statusOf } from "./validate.mjs";

export const CONTRACT = ["gate.mjs", "validate.mjs", "game.schema.json", "content.schema.json"];
export const fileHash = (text) => createHash("sha256").update(text).digest("hex").slice(0, 16);

/** Errors for the generated model folder (site/src/content/model): contract, stamps, schema, rules. */
export function gate(dir) {
  const errs = [], contract = join(dir, "_contract"), read = (f) => readFileSync(f, "utf8");
  const manifest = JSON.parse(read(join(contract, "manifest.json")));
  for (const f of CONTRACT) if (manifest.files[f] !== fileHash(read(join(contract, f)))) errs.push(`_contract/${f}: edited by hand; regenerate with fe content collections`);
  const model = { games: [], brands: [], posts: [], pages: [] };
  for (const c of Object.keys(model)) {
    const sub = join(dir, c);
    for (const f of existsSync(sub) ? readdirSync(sub).sort() : []) {
      const at = `${c}/${f}`, file = JSON.parse(read(join(sub, f)));
      errs.push(...checkStamp(file, at));
      if (file.collection !== c || `${file.id}.json` !== f) errs.push(`${at}: file name and collection must match its id`);
      if (file.status !== statusOf(c, file.data)) errs.push(`${at}: status ${file.status} does not match its data`);
      model[c].push(file.data);
    }
  }
  const schemas = { game: JSON.parse(read(join(contract, "game.schema.json"))), content: JSON.parse(read(join(contract, "content.schema.json"))) };
  errs.push(...checkModel(model, schemas));
  return { errs, counts: Object.fromEntries(Object.entries(model).map(([c, v]) => [c, v.length])) };
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const dir = process.argv[2] ?? dirname(dirname(fileURLToPath(import.meta.url)));
  const { errs, counts } = gate(dir);
  for (const e of errs) console.error(`✗ ${e}`);
  console.log(`${errs.length ? "✗" : "✓"} content model: ${Object.entries(counts).map(([c, n]) => `${n} ${c}`).join(", ")}${errs.length ? `, ${errs.length} error(s)` : ""}`);
  process.exit(errs.length ? 1 : 0);
}
